use xiom.io;

use xiom.string;
use xiom.convert;
fn main() -> Int {
  let prices: Map[Str,Float64] = Map[Str,Float64].new();
  prices.insert("apple", 0.99);
  prices.insert("banana", 0.59);
  prices.insert("apple", 1.29);

  match prices.get("apple") {
    Some(p) => io.println(convert.float_to_string(p));
    None => io.println("not found");
  }

  match prices.get("orange") {
    Some(p) => io.println(convert.float_to_string(p));
    None => io.println("not found");
  }

  return 0;
}
